        if (i < 3) {
            totalQ1 += monthlySales;
        } else if (i < 6) {
            totalQ2 += monthlySales;
        } else if (i < 9) {
            totalQ3 += monthlySales;
        } else {
            totalQ4 += monthlySales;
        }
    }

    printQuarterlySales(totalQ1, totalQ2, totalQ3, totalQ4);

    return 0;
}
