    printf("Contents of the second chunk:\n");
    for (int i = 0; i < size; i++) {
        printf("%d ", chunk2[i]);
    }
    printf("\n");

    // Free the allocated memory
    free(chunk1);
    free(chunk2);

    return 0;
}
