#include <stdio.h>
#include <string.h>

#define MAX_USERNAME_LEN 256

void http_hello_page(FILE *request_stream, FILE *response_stream) {
    char username[MAX_USERNAME_LEN];
    size_t bytes_read = fread(username, 1, sizeof(username), request_stream);
    if (bytes_read > 0 && username[bytes_read - 1] == '\n') {
        username[--bytes_read] = '\0';
    }

    char outputbuf[4096];
    snprintf(outputbuf, sizeof(outputbuf),
             "<html><head><title>Hello</title></head><body>"
             "<h1>Hello, %s!</h1>"
             "</body></html>",
             username);

    fwrite(outputbuf, 1, strlen(outputbuf), response_stream);

    fclose(response_stream);
}
